def vflip(grid):
    """The grid upside down."""
    return grid[::-1]

def hjoin_mirror(grid):
    """Each row followed by its horizontal mirror, doubling the width."""
    return [r + r[::-1] for r in grid]

def rev_rows(grid):
    """Each row reversed left to right."""
    return [r[::-1] for r in grid]

def vtile_mirror3(grid):
    """The grid, then its vertical mirror, then the grid again, stacked."""
    return grid + grid[::-1] + grid

from lib import vflip, rev_rows, hjoin_mirror, vtile_mirror3

def transform(grid):
    return vtile_mirror3(hjoin_mirror(rev_rows(vflip(grid))))

